import test from "node:test";
import assert from "node:assert/strict";
import {planner} from "./replay.mjs";
import {Ledger} from "./common/ledger.mjs";
import {bookStudio} from "./services/studio.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const book = (id, units, tenant = "orchid", day = "2025-04-02", service = "studio") =>
  ({action: "book", service, id, units, tenant, day});
const renew = (previous, id, day, units) =>
  ({action: "renew", service: "studio", previous, id, day, ...(units === undefined ? {} : {units})});

test("Studio allocations can exceed or restrict the default without affecting Archive", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("orchid", 8)), {status: "booked", id: "orchid", remaining: 0});
  assert.equal(dispatch(book("iris-full", 4, "iris")).status, "full");
  assert.equal(dispatch(book("iris", 3, "iris")).status, "booked");
  assert.equal(dispatch(book("fallback-full", 6, "lily")).status, "full");
  assert.equal(dispatch(book("fallback", 5, "lily")).status, "booked");
  assert.equal(dispatch(book("archive-full", 6, "orchid", "2025-04-02", "archive")).status, "full");
  assert.equal(dispatch(book("archive", 5, "orchid", "2025-04-02", "archive")).status, "booked");
});

test("admission keeps replay, conflicts, cancellation and tenant/day accounting", () => {
  const dispatch = planner(catalog);
  const request = book("morning", 7);
  assert.equal(dispatch(request).status, "booked");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 9}).status, "conflict");
  assert.deepEqual(dispatch(book("too-much", 2)), {status: "full", id: "too-much", remaining: 1});
  assert.equal(dispatch(book("next-day", 8, "orchid", "2025-04-03")).status, "booked");
  assert.deepEqual(dispatch({action: "usage", service: "studio", tenant: "orchid", day: request.day}), {units: 7});
  assert.equal(dispatch({action: "cancel", service: "studio", id: request.id}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({action: "cancel", service: "studio", id: request.id}).status, "replay");
  assert.equal(dispatch(book("too-much", 2)).status, "booked");
  const summary = dispatch({action: "summary", service: "studio"});
  assert.equal(summary.events.length, 4);
  assert.equal(summary.occupied.length, 2);
});

test("monthly renewals inherit the tenant allocation and use the same journal", () => {
  const dispatch = planner(catalog);
  dispatch(book("original", 7));
  const next = renew("original", "may", "2025-05-02");
  assert.deepEqual(dispatch(next), {status: "booked", id: "may", remaining: 1});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units: 9}).status, "conflict");
  assert.equal(dispatch(renew("original", "may-full", "2025-05-02", 2)).status, "full");
  assert.equal(dispatch(renew("original", "june-full", "2025-06-02", 9)).status, "full");
  assert.equal(dispatch(renew("original", "june", "2025-06-02", 8)).status, "booked");
  dispatch({action: "cancel", service: "studio", id: "may"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch(renew("may", "inactive", "2025-06-02")).status, "missing");
  assert.equal(dispatch(renew("absent", "missing", "2025-06-02")).status, "missing");
  dispatch(book("fallback", 5, "lily"));
  assert.equal(dispatch(renew("fallback", "fallback-full", "2025-05-02", 6)).status, "full");
  assert.equal(dispatch(renew("fallback", "fallback-next", "2025-05-02")).status, "booked");
  dispatch(book("archive", 5, "orchid", "2025-04-02", "archive"));
  assert.equal(dispatch({...renew("archive", "archive-next", "2025-05-02", 6), service: "archive"}).status, "full");
});

test("imports bypass admission, but their active units count toward capacity", () => {
  const dispatch = planner(catalog);
  assert.equal(dispatch({...book("imported", 10), action: "import"}).status, "imported");
  assert.deepEqual(dispatch(book("blocked", 1)), {status: "full", id: "blocked", remaining: 0});
  assert.equal(dispatch(book("imported", 10)).status, "replay");
  dispatch({action: "cancel", service: "studio", id: "imported"});
  assert.equal(dispatch(book("blocked", 1)).status, "booked");
});

test("the Studio adapter does not mutate the caller's ledger catalog", () => {
  const ledger = new Ledger(catalog);
  assert.equal(bookStudio(ledger, book("studio", 7), catalog).status, "booked");
  assert.equal(ledger.catalog, catalog);
  assert.equal(catalog.default, 5);
  assert.equal(ledger.usage("orchid", "2025-04-02"), 7);
  assert.equal(ledger.reserve(book("default-only", 6, "orchid", "2025-04-03")).status, "full");
});
