test("the pilot publishes only its audience and inclusive dates, including idle days", () => {
  assert.equal(projectCalendar(pilot, catalog).length, 12);
  assert.deepEqual(projectPublication(pilot, catalog), [
    {service: "studio", tenant: "orchid", day: "2025-04-02", edition: "orchid-quota", cap: 8, used: 7, available: 1},
    {service: "studio", tenant: "orchid", day: "2025-04-03", edition: "orchid-quota", cap: 8, used: 0, available: 8}
  ]);
});

test("publication replays history outside the window before projecting usage", () => {
  const source = structuredClone(pilot);
  source.operations = [
    {action: "book", service: "studio", tenant: "orchid", id: "previous", units: 7, day: "2025-03-02"},
    {action: "renew", service: "studio", previous: "previous", id: "renewed", day: "2025-04-02"},
    {action: "book", service: "studio", tenant: "orchid", id: "cancelled", units: 1, day: "2025-04-02"},
    {action: "cancel", service: "studio", id: "cancelled"},
    {action: "import", service: "studio", tenant: "orchid", id: "backfill", units: 10, day: "2025-04-03"}
  ];
  const rows = projectPublication(source, catalog);
  assert.deepEqual(rows.map(({used, available}) => ({used, available})), [
    {used: 7, available: 1}, {used: 10, available: 0}
  ]);
});

test("publication supports Archive and unlisted tenants using default capacity", () => {
  for (const [service, tenant] of [["archive", "orchid"], ["studio", "lily"]]) {
    const source = {...pilot, subscriptions: [{service, tenant}], window: {...pilot.window, service, tenant}};
    assert.ok(projectPublication(source, catalog).every(row => row.cap === 5 && row.available === 5));
  }
});

test("invalid publication windows are rejected", () => {
  for (const window of [undefined, {...pilot.window, service: "other"}, {...pilot.window, tenant: "!"},
    {...pilot.window, from: "2025-02-30"}, {...pilot.window, through: "2025-04-01"}]) {
    assert.throws(() => projectPublication({...pilot, window}, catalog));
  }
});

test("publish-calendar preserves other cells and is byte-for-byte idempotent", () => {
  const dir = mkdtempSync(join(tmpdir(), "orchid-calendar-"));
  try {
    const feed = join(dir, "feed.json");
    const diary = join(dir, "diary.json");
    const seed = projectCalendar(pilot, catalog).map(row => ({...row, edition: "signed-spring", cap: 5, used: 4, available: 1}));
    writeFileSync(feed, JSON.stringify(pilot));
    writeFileSync(diary, JSON.stringify(seed));
    const publish = () => JSON.parse(execFileSync(process.execPath,
      [new URL("./utilization.mjs", import.meta.url).pathname, "publish-calendar", feed, diary], {encoding: "utf8"}));
    assert.deepEqual(publish(), {edition: "orchid-quota", rows: 2});
    const first = readFileSync(diary, "utf8");
    const actual = new Map(JSON.parse(first).map(row => [key(row), row]));
    const updates = new Map(projectPublication(pilot, catalog).map(row => [key(row), row]));
    assert.equal(actual.size, seed.length);
    for (const row of seed) assert.deepEqual(actual.get(key(row)), updates.get(key(row)) ?? row);
    publish();
    assert.equal(readFileSync(diary, "utf8"), first);
    writeFileSync(feed, JSON.stringify({...pilot, window: {...pilot.window, through: "2025-04-01"}}));
    assert.throws(publish);
    assert.equal(readFileSync(diary, "utf8"), first);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});
