import {readCatalog} from "./common/limits.mjs";

test("Studio-only staging preserves existing queue records and is idempotent", () => {
  const dir = mkdtempSync(join(tmpdir(), "orchid-queue-"));
  try {
    mkdirSync(join(dir, "fixtures"));
    const file = join(dir, "fixtures", "release-queue.json");
    const existing = {release: "summer", service: "archive", default: 5, allocations: {}};
    writeFileSync(file, JSON.stringify([existing]));
    const stage = (...args) => execFileSync(process.execPath,
      [new URL("./replay.mjs", import.meta.url).pathname, "stage", ...args], {cwd: dir, encoding: "utf8"});
    const catalog = readCatalog();
    stage("orchid-quota", "studio");
    const first = readFileSync(file, "utf8");
    assert.deepEqual(JSON.parse(first), [existing, {
      release: "orchid-quota", service: "studio", default: catalog.default,
      allocations: Object.fromEntries(catalog.studios)
    }]);
    stage("orchid-quota", "studio");
    assert.equal(readFileSync(file, "utf8"), first);
    assert.throws(() => stage("invalid", "other"));
    assert.equal(readFileSync(file, "utf8"), first);
    stage("coordinated");
    assert.deepEqual(JSON.parse(readFileSync(file, "utf8")).slice(2).map(row => row.service), ["studio", "archive"]);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});
